const input = $json;

const errors = [];

const validPriorities = ['Critical', 'High', 'Medium', 'Low'];

function isValidDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(value || '');
}

function isMonday(dateString) {
  const d = new Date(`${dateString}T00:00:00Z`);
  return d.getUTCDay() === 1;
}

function isNonNegativeNumber(value) {
  return typeof value === 'number' &&
         Number.isFinite(value) &&
         value >= 0;
}

// --------------------
// Project validation
// --------------------
if (!input.project) {
  errors.push('project object is required');
} else {
  if (!/^PRJ-\d{3}$/.test(input.project.project_id || '')) {
    errors.push('project.project_id must follow PRJ-###');
  }

  if (!input.project.project_name) {
    errors.push('project.project_name is required');
  }

  if (!validPriorities.includes(input.project.priority)) {
    errors.push('project.priority must be Critical, High, Medium or Low');
  }

  if (!isValidDate(input.project.start_date)) {
    errors.push('project.start_date must use YYYY-MM-DD');
  }

  if (!isValidDate(input.project.end_date)) {
    errors.push('project.end_date must use YYYY-MM-DD');
  }

  if (
    isValidDate(input.project.start_date) &&
    isValidDate(input.project.end_date) &&
    input.project.end_date < input.project.start_date
  ) {
    errors.push('project.end_date cannot be before start_date');
  }
}

// --------------------
// Resource validation
// --------------------
if (!input.resource) {
  errors.push('resource object is required');
} else {
  if (!/^RES-\d{3}$/.test(input.resource.resource_id || '')) {
    errors.push('resource.resource_id must follow RES-###');
  }

  if (!input.resource.resource_name) {
    errors.push('resource.resource_name is required');
  }

  if (!input.resource.role) {
    errors.push('resource.role is required');
  }

  if (!input.resource.department) {
    errors.push('resource.department is required');
  }

  if (!isNonNegativeNumber(input.resource.standard_weekly_hours)) {
    errors.push(
      'resource.standard_weekly_hours must be a non-negative number'
    );
  }
}

// --------------------
// Capacity validation
// --------------------
if (!input.capacity) {
  errors.push('capacity object is required');
} else {
  if (!isValidDate(input.capacity.week_start_date)) {
    errors.push('capacity.week_start_date must use YYYY-MM-DD');
  } else if (!isMonday(input.capacity.week_start_date)) {
    errors.push('capacity.week_start_date must be a Monday');
  }

  const capacityFields = [
    'standard_hours',
    'leave_hours',
    'holiday_hours',
    'training_hours',
    'bau_hours'
  ];

  for (const field of capacityFields) {
    if (!isNonNegativeNumber(input.capacity[field])) {
      errors.push(`capacity.${field} must be a non-negative number`);
    }
  }
}

// --------------------
// Demand validation
// --------------------
if (!Array.isArray(input.demand) || input.demand.length === 0) {
  errors.push('demand must contain at least one activity');
} else {
  input.demand.forEach((d, index) => {
    if (!/^PRJ-\d{3}$/.test(d.project_id || '')) {
      errors.push(`demand[${index}].project_id must follow PRJ-###`);
    }

    if (!d.activity_name) {
      errors.push(`demand[${index}].activity_name is required`);
    }

    if (!isNonNegativeNumber(d.planned_hours)) {
      errors.push(
        `demand[${index}].planned_hours must be a non-negative number`
      );
    }

    if (!validPriorities.includes(d.priority)) {
      errors.push(
        `demand[${index}].priority must be Critical, High, Medium or Low`
      );
    }

    if (typeof d.critical_path !== 'boolean') {
      errors.push(
        `demand[${index}].critical_path must be true or false`
      );
    }
  });
}

// --------------------
// Final result
// --------------------
if (errors.length > 0) {
  return {
    json: {
      validation_status: 'FAILED',
      valid: false,
      error_count: errors.length,
      errors,
      original_payload: input
    }
  };
}

return {
  json: {
    validation_status: 'PASSED',
    valid: true,
    error_count: 0,
    errors: [],
    payload: input
  }
};

