const payload = $json.payload;

// Normalize project
const project = {
  project_id: payload.project.project_id.trim().toUpperCase(),
  project_name: payload.project.project_name.trim(),
  priority: payload.project.priority,
  status: payload.project.status || 'Active',
  start_date: payload.project.start_date,
  end_date: payload.project.end_date
};

// Normalize resource
const resource = {
  resource_id: payload.resource.resource_id.trim().toUpperCase(),
  resource_name: payload.resource.resource_name.trim(),
  role: payload.resource.role.trim(),
  department: payload.resource.department.trim(),
  standard_weekly_hours: Number(payload.resource.standard_weekly_hours),
  active: payload.resource.active !== false
};

// Normalize capacity
const capacity = {
  resource_id: resource.resource_id,
  week_start_date: payload.capacity.week_start_date,
  standard_hours: Number(payload.capacity.standard_hours),
  leave_hours: Number(payload.capacity.leave_hours || 0),
  holiday_hours: Number(payload.capacity.holiday_hours || 0),
  training_hours: Number(payload.capacity.training_hours || 0),
  bau_hours: Number(payload.capacity.bau_hours || 0)
};

// Normalize demand
const demand = payload.demand.map((d, index) => ({
  demand_sequence: index + 1,
  resource_id: resource.resource_id,
  project_id: d.project_id.trim().toUpperCase(),
  week_start_date: payload.capacity.week_start_date,
  activity_name: d.activity_name.trim(),
  planned_hours: Number(d.planned_hours),
  priority: d.priority,
  critical_path: Boolean(d.critical_path)
}));

return {
  json: {
    intake_status: 'NORMALIZED',
    project,
    resource,
    capacity,
    demand,
    demand_count: demand.length
  }
};

const normalized =
  $node["Normalize Planning Data"].json;

return normalized.demand.map(d => ({
  json: {
    resource_id: d.resource_id,
    project_id: d.project_id,
    week_start_date: d.week_start_date,
    activity_name: d.activity_name,
    planned_hours: d.planned_hours,
    priority: d.priority,
    critical_path: d.critical_path
  }
}));

return [{
  json: {
    resource_id:
      $items("Normalize Planning Data")[0].json.resource.resource_id,

    week_start_date:
      $items("Normalize Planning Data")[0].json.capacity.week_start_date
  }
}];

const normalized =
  $items("Normalize Planning Data")[0].json;

const conflictItems =
  $items("Recalculate Capacity Conflicts");

const conflict =
  conflictItems.length > 0
    ? conflictItems[0].json
    : null;

return [{
  json: {
    intake_status: 'COMPLETED',

    project: {
      project_id: normalized.project.project_id,
      project_name: normalized.project.project_name
    },

    resource: {
      resource_id: normalized.resource.resource_id,
      resource_name: normalized.resource.resource_name,
      role: normalized.resource.role,
      department: normalized.resource.department
    },

    capacity: {
      week_start_date: normalized.capacity.week_start_date,
      standard_hours: normalized.capacity.standard_hours,
      leave_hours: normalized.capacity.leave_hours,
      holiday_hours: normalized.capacity.holiday_hours,
      training_hours: normalized.capacity.training_hours,
      bau_hours: normalized.capacity.bau_hours
    },

    demand: {
      activities_processed: normalized.demand.length,
      total_planned_hours: normalized.demand.reduce(
        (sum, d) => sum + Number(d.planned_hours),
        0
      )
    },

    conflict_detected: conflict !== null,

    conflict: conflict
      ? {
          conflict_id: conflict.conflict_id,
          utilization_pct: Number(conflict.utilization_pct),
          overallocation_hours: Number(conflict.overallocation_hours),
          severity: conflict.severity,
          status: conflict.status
        }
      : null
  }
}];
